func TestSettleOrder(t *testing.T) {
	ctrl := gomock.NewController(t)
	store := NewMockOrderStore(ctrl)
	gw := NewMockGateway(ctrl)

	order := Order{ID: "o-17", AmountCents: 4999}
	gomock.InOrder(
		store.EXPECT().Get(gomock.Any(), "o-17").Return(order, nil),
		gw.EXPECT().Charge(gomock.Any(), gomock.Any(), gomock.Any()).Return(nil),
		store.EXPECT().Save(gomock.Any(), gomock.Any()).Return(nil),
	)

	svc := NewBilling(store, gw)
	if err := svc.Settle(context.Background(), "o-17"); err != nil {
		t.Fatal(err)
	}
}

